function guideContainer(step){const target=$(step.target);return target?.closest('.param, .source-options')||(step.target==='#keyboard'?$('.keyboard-header'):target);}
function highlightGuideTargets(){
 $$('.guide-target').forEach(el=>{el.classList.remove('guide-target','guide-focused');delete el.dataset.guideLabel;});
 if(currentLesson===lessons.length-1)return;
 lessonGuides[currentLesson].forEach((step,i)=>{if(step.source&&engine!==lessons[currentLesson].engine)return;const el=guideContainer(step);if(el){el.classList.add('guide-target');el.dataset.guideLabel=`STEP ${i+1} · ${step.label.replace(' · LEARN','').toUpperCase()}`;}});
}
function showGuideStep(index){
 const step=lessonGuides[currentLesson][index];
 if(step.source&&engine!==lessons[currentLesson].engine){changeEngine(lessons[currentLesson].engine);$('#preset').value='init';}
 $$('.guide-focused').forEach(el=>el.classList.remove('guide-focused'));
 const container=guideContainer(step),target=$(step.target);
 if(!target||!container)return;
 container.classList.add('guide-focused');
 // All controls stay in the fitted workstation; focus without scrolling.
 (step.target==='#keyboard'?$('#keyboard .key'):target).focus({preventScroll:true});
}
function renderLessonGuide(){
 let guide=$('#lesson-guide');
 if(!guide){guide=document.createElement('div');guide.id='lesson-guide';guide.className='lesson-guide';$('#lesson-task').after(guide);}
 guide.replaceChildren();const title=document.createElement('h3');title.textContent='WHERE TO DO IT · FOLLOW THE NUMBERED CONTROLS';guide.append(title);
 const tabs=document.createElement('div');tabs.className='guide-step-tabs';tabs.setAttribute('aria-label','Tutorial steps');guide.append(tabs);const list=document.createElement('ol');guide.append(list);
 lessonGuides[currentLesson].forEach((step,i)=>{const row=document.createElement('li');row.className='guide-step';row.hidden=i!==0;const tab=document.createElement('button');tab.textContent='Step '+(i+1);tab.setAttribute('aria-pressed',String(i===0));tab.onclick=()=>{[...list.children].forEach((el,j)=>el.hidden=j!==i);[...tabs.children].forEach((el,j)=>el.setAttribute('aria-pressed',String(j===i)));};tabs.append(tab);const number=document.createElement('span');number.className='step-number';number.textContent=i+1;const body=document.createElement('div'),text=document.createElement('p'),button=document.createElement('button');text.textContent=controllerText(step.text);button.textContent=`Show ${step.label} ↗ · ${step.location}`;button.onclick=()=>showGuideStep(i);body.append(text,button);row.append(number,body);list.append(row);});
 highlightGuideTargets();
}
function normalize(k,v){const d=definitions[k];return d.log?Math.log(v/d.min)/Math.log(d.max/d.min):(v-d.min)/(d.max-d.min);}
function denormalize(k,v){const d=definitions[k];let n=d.log?d.min*Math.pow(d.max/d.min,v):d.min+v*(d.max-d.min);return d.step?Math.round(n/d.step)*d.step:n;}
function setParam(k,v){const d=definitions[k];if(!d||!Number.isFinite(v))return;params[k]=Math.max(d.min,Math.min(d.max,v));const el=$('#param-'+k);if(el){el.value=normalize(k,params[k])*1000;$('#value-'+k).textContent=d.format(params[k]);}updateVoices(k);drawEnvelope();if(typeof updateLab==='function')updateLab();}
function renderParam(k,parent){const d=definitions[k],box=document.createElement('div');box.className='param';box.innerHTML=`<label for="param-${k}">${d.name}</label><input id="param-${k}" type="range" min="0" max="1000" step="1" value="${normalize(k,params[k])*1000}" aria-describedby="value-${k}"><output id="value-${k}">${d.format(params[k])}</output><button class="learn" data-learn="${k}" title="Map a MIDI CC to ${d.name}">LEARN</button><span class="hint">${d.hint}</span>`;$(parent).append(box);box.querySelector('input').addEventListener('input',e=>setParam(k,denormalize(k,+e.target.value/1000)));box.querySelector('button').onclick=()=>beginLearn(k);}
function renderControls(){for(const target of ['#source-controls','#tone-controls','#envelope-controls'])$(target).replaceChildren();engineInfo[engine].source.forEach(k=>renderParam(k,'#source-controls'));['cutoff','resonance','lfoRate','lfoDepth'].forEach(k=>renderParam(k,'#tone-controls'));['attack','decay','sustain','release'].forEach(k=>renderParam(k,'#envelope-controls'));$('.source-options').hidden=engine!=='subtractive';$('#source-label').textContent=engine.toUpperCase();$('#engine-description').textContent=engineInfo[engine].description;$('#listen-tip').textContent=engineInfo[engine].tip;$('#signal-path').innerHTML=engineInfo[engine].path.map((x,i)=>`${i?'<span>→</span>':''}<div class="node ${i===0?'accent':''}">${x}</div>`).join('');$('#path-caption').textContent=engineInfo[engine].caption;$$('[data-engine]').forEach(b=>b.setAttribute('aria-selected',b.dataset.engine===engine));drawEnvelope();renderMappings();highlightGuideTargets();if(currentLesson===lessons.length-1)updateLab();}
function changeEngine(value){if(!engineInfo[value])return;panic();engine=value;renderControls();}
function drawEnvelope(){const a=20+params.attack/3*45,d=32+params.decay/3*40,r=35+params.release/5*45,s=106-params.sustain*90;$('#env-line').setAttribute('d',`M 4 106 L ${a} 16 L ${a+d} ${s} L ${316-r} ${s} L 316 106 Z`);}
function selectLesson(index){panic();currentLesson=index;const finalLab=index===lessons.length-1;document.body.classList.toggle('final-lab',finalLab);$('#sound-lab').hidden=!finalLab;const l=lessons[index];params=Object.fromEntries(Object.entries(definitions).map(([k,d])=>[k,d.initial]));Object.assign(params,l.setup);waveform='sawtooth';$('#wave').value=waveform;$('#preset').value='init';changeEngine(l.engine);$('#lesson-kicker').textContent=`LESSON ${String(index+1).padStart(2,'0')} / ${String(lessons.length).padStart(2,'0')} · EXPLORE & LISTEN`;$('#lesson-title').textContent=l.title;$('#lesson-body').textContent=controllerText(l.body);$('#lesson-task').innerHTML='<b>TRY THIS → </b>'+l.task;if(index===lessons.length-1){const labButton=document.createElement('button');labButton.id='open-lab';labButton.className='primary';labButton.textContent='Open Sound Lab →';labButton.onclick=()=>openSoundLab();$('#lesson-task').append(document.createElement('br'),labButton);}renderLessonGuide();if(finalLab)updateLab();$('#lesson-result').textContent=completed.has(index)?'✓ Explored':'';renderNavigation();$('#quiz-question').textContent=l.question;$('#quiz-feedback').textContent='';$('#quiz-options').replaceChildren();l.answers.forEach((answer,i)=>{const b=document.createElement('button');b.textContent=answer;b.onclick=()=>{const right=i===l.correct;b.className=right?'correct':'wrong';$('#quiz-feedback').textContent=(right?'Exactly. ':'Try again. ')+l.explain;};$('#quiz-options').append(b);});}
function renderNavigation(){$('#lesson-nav').replaceChildren();lessons.forEach((l,i)=>{const b=document.createElement('button');b.className=i===currentLesson?'active':'';b.innerHTML=`<span class="num">${completed.has(i)?'✓':String(i+1).padStart(2,'0')}</span>${l.nav}`;b.onclick=()=>selectLesson(i);b.setAttribute('aria-current',i===currentLesson?'step':'false');$('#lesson-nav').append(b);});$('#progress-bar').style.width=completed.size/lessons.length*100+'%';$('#progress-text').textContent=`${completed.size} of ${lessons.length} lessons explored`;}
async function enableAudio(){if(audioStarting)return audioStarting;audioStarting=(async()=>{try{if(!ctx){ctx=new (window.AudioContext||window.webkitAudioContext)();master=ctx.createGain();master.gain.value=+$('#volume').value;compressor=ctx.createDynamicsCompressor();compressor.threshold.value=-14;compressor.knee.value=15;compressor.ratio.value=8;analyser=ctx.createAnalyser();analyser.fftSize=2048;master.connect(compressor).connect(analyser).connect(ctx.destination);}await ctx.resume();$('#audio-status').textContent='● Sound enabled';$('#audio-status').style.color='#55e7f4';$('#audio-start').textContent='Sound enabled ✓';return true;}catch(e){toast('Could not start audio: '+e.message);return false;}finally{audioStarting=null;}})();return audioStarting;}
function pitch(note){return 440*Math.pow(2,(note-69)/12);}
function noteName(n){return ['C','C♯','D','D♯','E','F','F♯','G','G♯','A','A♯','B'][n%12]+(Math.floor(n/12)-1);}
function makePeriodic(kind,frequency){const count=64,real=new Float32Array(count),imag=new Float32Array(count);for(let h=1;h<count;h++){if(h*frequency>ctx.sampleRate*.45)break;if(kind==='additive'){if(h<=Math.round(params.harmonics))imag[h]=1/Math.pow(h,params.tilt);}else{const p=params.position, sine=h===1?1:0,saw=(h%2?1:-1)/h,square=h%2?1/h:0;imag[h]=p<=.5?sine*(1-2*p)+saw*2*p:saw*(2-2*p)+square*(2*p-1);}}return ctx.createPeriodicWave(real,imag);}
function startVoice(id,note,velocity=100,channel='local'){if(!ctx||ctx.state!=='running')return;if(voices.has(id))endVoice(id,true);if(voices.size>=24)endVoice(voices.keys().next().value,true);const now=ctx.currentTime,freq=pitch(note),filter=ctx.createBiquadFilter(),amp=ctx.createGain(),lfo=ctx.createOscillator(),lfoGain=ctx.createGain();filter.type='lowpass';filter.frequency.value=params.cutoff;filter.Q.value=params.resonance;filter.connect(amp).connect(master);const level=.14*Math.max(.01,velocity/127);amp.gain.setValueAtTime(0,now);amp.gain.linearRampToValueAtTime(level,now+params.attack);amp.gain.linearRampToValueAtTime(level*params.sustain,now+params.attack+params.decay);const v={id,note,channel,freq,filter,amp,lfo,lfoGain,level,osc:[],gains:[],started:now,released:false,sustained:false,engine};lfo.frequency.value=params.lfoRate;lfoGain.gain.value=params.lfoDepth+(modulations.get(channel)||0)*70;lfo.connect(lfoGain);const osc=ctx.createOscillator();osc.frequency.value=freq;osc.detune.value=bends.get(channel)||0;if(engine==='fm'){osc.type='sine';const mod=ctx.createOscillator(),gain=ctx.createGain();mod.frequency.value=freq*params.fmRatio;gain.gain.value=freq*params.fmRatio*params.fmIndex;mod.connect(gain).connect(osc.frequency);mod.start();v.mod=mod;v.modGain=gain;}else if(engine==='subtractive'){osc.type=waveform;}else osc.setPeriodicWave(makePeriodic(engine,freq));osc.connect(filter);lfoGain.connect(osc.detune);v.osc.push(osc);if(engine==='subtractive'||engine==='wavetable'){const second=ctx.createOscillator();second.frequency.value=freq;second.detune.value=params.detune+(bends.get(channel)||0);if(engine==='subtractive')second.type=waveform;else second.setPeriodicWave(makePeriodic(engine,freq));const split=ctx.createGain();split.gain.value=.5;second.connect(split).connect(filter);lfoGain.connect(second.detune);second.start();v.osc.push(second);v.gains.push(split);}osc.start();lfo.start();voices.set(id,v);$('#note-label').textContent=noteName(note)+' · '+Math.round(freq)+' Hz';paintKeys();}
function endVoice(id,immediate=false){const v=voices.get(id);if(!v||!ctx)return;if(!immediate&&sustainChannels.has(v.channel)){v.sustained=true;return;}if(v.released&&!immediate)return;v.released=true;const now=ctx.currentTime,duration=immediate?.015:params.release;const gain=v.amp.gain;if(gain.cancelAndHoldAtTime)gain.cancelAndHoldAtTime(now);else{const t=now-v.started,peak=v.level,estimate=t<params.attack?peak*t/params.attack:t<params.attack+params.decay?peak+(peak*params.sustain-peak)*(t-params.attack)/params.decay:peak*params.sustain;gain.cancelScheduledValues(now);gain.setValueAtTime(Math.max(0,estimate),now);}gain.linearRampToValueAtTime(0,now+duration);v.sustained=false;for(const o of [...v.osc,v.lfo,...(v.mod?[v.mod]:[])]){try{o.stop(now+duration+.03);}catch{}}if(immediate)voices.delete(id);v.cleanup=setTimeout(()=>{if(voices.get(id)===v)voices.delete(id);v.filter.disconnect();v.amp.disconnect();v.lfoGain.disconnect();v.modGain?.disconnect();v.gains.forEach(g=>g.disconnect());paintKeys();},duration*1000+60);paintKeys();}
function panic(){demoTimers.forEach(clearTimeout);demoTimers=[];for(const id of [...voices.keys()])endVoice(id,true);voices.clear();heldComputer.clear();sustainChannels.clear();paintKeys();}
function updateVoices(k){if(!ctx)return;const now=ctx.currentTime;for(const v of voices.values()){if(v.released)continue;if(k==='cutoff')v.filter.frequency.setTargetAtTime(params.cutoff,now,.015);if(k==='resonance')v.filter.Q.setTargetAtTime(params.resonance,now,.015);if(k==='lfoRate')v.lfo.frequency.setTargetAtTime(params.lfoRate,now,.02);if(k==='lfoDepth')v.lfoGain.gain.setTargetAtTime(params.lfoDepth+(modulations.get(v.channel)||0)*70,now,.02);if(k==='detune'&&v.osc[1])v.osc[1].detune.setTargetAtTime(params.detune+(bends.get(v.channel)||0),now,.02);if((k==='fmRatio'||k==='fmIndex')&&v.mod){v.mod.frequency.setTargetAtTime(v.freq*params.fmRatio,now,.02);v.modGain.gain.setTargetAtTime(v.freq*params.fmRatio*params.fmIndex,now,.02);}if(['harmonics','tilt','position'].includes(k)&&['additive','wavetable'].includes(v.engine))for(const o of v.osc)o.setPeriodicWave(makePeriodic(v.engine,v.freq));}}
const computerKeys=['a','w','s','e','d','f','t','g','y','h','u','j','k'];
function renderKeyboard(){const start=(octave+1)*12,end=start+24;$('#keyboard').replaceChildren();const whites=[];for(let n=start;n<=end;n++)if(![1,3,6,8,10].includes(n%12))whites.push(n);let white=0;for(let n=start;n<=end;n++){const black=[1,3,6,8,10].includes(n%12),b=document.createElement('button');b.className='key'+(black?' black':'');b.dataset.note=n;b.setAttribute('aria-label',noteName(n));b.style.left=(black?(white/whites.length*100-2.1):(white/whites.length*100))+'%';if(!black)b.style.width=100/whites.length+'%';b.textContent=computerKeys[n-start]?.toUpperCase()||(n%12===0?noteName(n):'');b.addEventListener('pointerdown',async e=>{e.preventDefault();b.setPointerCapture(e.pointerId);const id='pointer:'+e.pointerId;b.dataset['held'+e.pointerId]='yes';if(await enableAudio())if(b.dataset['held'+e.pointerId])startVoice(id,n,100);});const stop=e=>{delete b.dataset['held'+e.pointerId];endVoice('pointer:'+e.pointerId);};b.onpointerup=stop;b.onpointercancel=stop;b.onlostpointercapture=stop;$('#keyboard').append(b);if(!black)white++;}$('#octave-label').textContent=`C${octave} — C${octave+2}`;}
function paintKeys(){const active=new Set([...voices.values()].filter(v=>!v.released).map(v=>v.note));$$('.key').forEach(k=>k.classList.toggle('active',active.has(+k.dataset.note)));$('#voice-count').textContent=[...voices.values()].filter(v=>!v.released).length+' VOICES';}
function drawScope(){requestAnimationFrame(drawScope);const canvas=$('#scope'),g=canvas.getContext('2d'),w=canvas.width,h=canvas.height;g.clearRect(0,0,w,h);g.strokeStyle='#302446';g.lineWidth=1;for(let x=0;x<w;x+=w/12){g.beginPath();g.moveTo(x,0);g.lineTo(x,h);g.stroke();}for(let y=0;y<=h;y+=h/6){g.beginPath();g.moveTo(0,y);g.lineTo(w,y);g.stroke();}g.strokeStyle='#55e7f4';g.lineWidth=2;g.beginPath();if(analyser){const data=new Float32Array(analyser.fftSize);analyser.getFloatTimeDomainData(data);let offset=0;for(let i=1;i<400;i++)if(data[i-1]<0&&data[i]>=0){offset=i;break;}for(let x=0;x<w;x++){const value=data[Math.min(data.length-1,offset+Math.floor(x/w*1200))]||0,y=h/2-value*h*.85;x?g.lineTo(x,y):g.moveTo(x,y);}}else{g.moveTo(0,h/2);g.lineTo(w,h/2);}g.stroke();}
function beginLearn(k){if(!selectedInput){toast('Connect MIDI and select an input first.');return;}learnQueue=[];learnLastKey=null;learnTarget=learnTarget===k?null:k;renderMappings();toast(learnTarget?'Move a knob or fader for '+definitions[k].name:'MIDI Learn cancelled.');}
function renderMappings(){if(!maps||typeof maps!=='object')maps={};const inputMaps=maps[selectedInput]||{};$$('[data-learn]').forEach(b=>{const k=b.dataset.learn,entries=Object.entries(inputMaps).filter(([,v])=>v===k);b.className='learn'+(learnTarget===k?' learning':entries.length?' mapped':'');b.textContent=learnTarget===k?'MOVE CONTROL…':entries.length?'CC '+entries[0][0].split(':')[1]:'LEARN';});$('#mapping-list').dataset.summary=Object.values(inputMaps).filter(k=>definitions[k]).length+' controls mapped';$('#mapping-list').replaceChildren();for(const [key,param]of Object.entries(inputMaps)){if(!definitions[param])continue;const span=document.createElement('span');span.textContent=`CH ${+key.split(':')[0]+1} · CC ${key.split(':')[1]} → ${definitions[param].name}`;$('#mapping-list').append(span);}$('#learn-all').textContent=learnQueue.length||learnTarget?'Cancel learning':'Map controls';}
const controllerActivity=new Map();
function controllerName(){return midiAccess?.inputs.get(selectedInput)?.name||'Your MIDI controller';}
function controllerText(text){return text.replaceAll('{controller}',controllerName());}
function updateControllerUI(){
 const device=midiAccess?.inputs.get(selectedInput),activity=controllerActivity.get(selectedInput);
 $('#controller-title').textContent=device?controllerName():'Connect a MIDI controller';
 $('#controller-title').title=device?[device.manufacturer,device.name].filter(Boolean).join(' · '):'Select a MIDI input';
 $('#controller-help-name').textContent=device?controllerName():'MIDI CONTROLLER SETUP';
 const observations=[];if(activity?.notes)observations.push('Notes / pads');if(activity?.cc.size)observations.push(activity.cc.size+' CC controls');if(activity?.bend)observations.push('Pitch bend');if(activity?.sustain)observations.push('Sustain');
 $('#controller-details').textContent=device?[(device.manufacturer||'MIDI device'),...observations].join(' · '):'Device names are detected after you allow MIDI access.';
 $('#controller-details').title=$('#controller-details').textContent;
 $$('[data-controller-name]').forEach(el=>el.textContent=controllerName());
 $('#learn-all').disabled=!device;$('#clear-mappings').disabled=!device;
 if(currentLesson===7)$('#lesson-body').textContent=controllerText(lessons[7].body);
 $$('#lesson-guide .guide-step p').forEach((el,index)=>el.textContent=controllerText(lessonGuides[currentLesson][index].text));
}
function syncInputs(){
 const previous=selectedInput;const connected=[...midiAccess.inputs.values()].filter(input=>input.state==='connected');
 $('#midi-input').replaceChildren();
 for(const input of midiAccess.inputs.values())input.onmidimessage=null;
 for(const input of connected){const option=document.createElement('option');option.value=input.id;option.textContent=input.name||input.manufacturer||'Unnamed MIDI input';$('#midi-input').append(option);input.onmidimessage=event=>{if(selectedInput===input.id)handleMidi(event.data);};}
 selectedInput=connected.some(input=>input.id===previous)?previous:(connected.find(input=>input.id===preferredInput)||connected[0])?.id||'';
 if(previous!==selectedInput){panic();bends.clear();modulations.clear();}
 $('#midi-input').value=selectedInput;learnTarget=null;learnQueue=[];learnLastKey=null;
 if(!selectedInput){const option=document.createElement('option');option.textContent='No input connected';$('#midi-input').append(option);}
 $('#midi-status').textContent=selectedInput?'Connected: '+controllerName()+'. Notes play the synth; use LEARN for CC controls.':'MIDI allowed. No inputs found — connect a controller or enable its MIDI port.';
 renderMappings();updateControllerUI();
}
function observeController(type,a,b){
 if(!selectedInput)return;let activity=controllerActivity.get(selectedInput);if(!activity){activity={notes:false,cc:new Set(),bend:false,sustain:false};controllerActivity.set(selectedInput,activity);}
 let changed=false;
 if(type===144&&b&&!activity.notes){activity.notes=true;changed=true;}
 if(type===176&&![120,123].includes(a)&&!activity.cc.has(a)){activity.cc.add(a);changed=true;}
 if(type===224&&!activity.bend){activity.bend=true;changed=true;}
 if(type===176&&a===64&&!activity.sustain){activity.sustain=true;changed=true;}
 if(changed)updateControllerUI();
}

async function connectMidi(){if(!navigator.requestMIDIAccess){$('#midi-status').textContent='Web MIDI is unavailable here. Open this localhost app in Edge or Chrome. Computer keys and touch still work.';return;}try{await enableAudio();midiAccess=await navigator.requestMIDIAccess({sysex:false});midiAccess.onstatechange=event=>{if(event.port.type==='input')syncInputs();};syncInputs();$('#midi-connect').textContent='Refresh MIDI';}catch(e){$('#midi-status').textContent='MIDI access was not granted. Check browser site permissions and reconnect. '+e.message;}}
function handleMidi(data){const [status,a,b=0]=data,type=status&0xf0,ch=status&15;observeController(type,a,b);const channel=selectedInput+':'+ch,id='midi:'+channel+':'+a;$('#midi-monitor').textContent=`MIDI monitor: channel ${ch+1} · ${type===176?'CC '+a+' = '+b:type===144&&b?'Note '+noteName(a)+' · velocity '+b:type===128||type===144?'Note off '+noteName(a):type===224?'Pitch bend':'message '+status}`;if(type===144&&b){startVoice(id,a,b,channel);}else if(type===128||(type===144&&!b)){endVoice(id);}else if(type===176){if(a===120||a===123){for(const [voiceId,v]of voices)if(v.channel===channel)endVoice(voiceId,true);return;}if(a===64){if(b>=64)sustainChannels.add(channel);else{sustainChannels.delete(channel);for(const [voiceId,v]of voices)if(v.channel===channel&&v.sustained)endVoice(voiceId);}return;}const key=ch+':'+a;if(learnTarget){if(key===learnLastKey)return;learnLastKey=key;const target=learnTarget;maps[selectedInput]??={};for(const [old,value]of Object.entries(maps[selectedInput]))if(value===target)delete maps[selectedInput][old];maps[selectedInput][key]=target;storage.set('maps',maps);learnTarget=learnQueue.shift()||null;renderMappings();toast(learnTarget?`Mapped ${definitions[target].name}. Now move another control for ${definitions[learnTarget].name}.`:'Mapping saved.');return;}const target=maps[selectedInput]?.[key];if(definitions[target])setParam(target,denormalize(target,b/127));else if(a===1){modulations.set(channel,b/127);updateVoices('lfoDepth');}}else if(type===224){const cents=((a+(b<<7))-8192)/8192*200;bends.set(channel,cents);if(ctx)for(const v of voices.values())if(v.channel===channel&&!v.released)v.osc.forEach((o,i)=>o.detune.setTargetAtTime(cents+(i?params.detune:0),ctx.currentTime,.01));}}
function snapshot(){return {format:'signal-school',version:1,engine,waveform,params:{...params},volume:+$('#volume').value};}
function applyPatch(p){if(!p||p.format!=='signal-school'||p.version!==1||!engineInfo[p.engine]||!['sawtooth','square','triangle','sine'].includes(p.waveform)||!p.params||Object.keys(definitions).some(k=>typeof p.params[k]!=='number'||!Number.isFinite(p.params[k])))throw Error('This is not a valid Signal School patch.');panic();for(const [k,d]of Object.entries(definitions))params[k]=Math.max(d.min,Math.min(d.max,p.params[k]));waveform=p.waveform;$('#wave').value=waveform;changeEngine(p.engine);if(Number.isFinite(p.volume)){$('#volume').value=Math.max(0,Math.min(.65,p.volume));updateVolume();}$('#preset').value='init';}
const presets={bass:{engine:'subtractive',waveform:'sawtooth',params:{cutoff:650,resonance:3,attack:.005,decay:.18,sustain:.4,release:.12,detune:7}},pad:{engine:'subtractive',waveform:'triangle',params:{cutoff:4000,attack:1.3,decay:.8,sustain:.8,release:2.8,detune:10,lfoDepth:7,lfoRate:.6}},bell:{engine:'fm',params:{fmRatio:2.73,fmIndex:3,cutoff:17000,attack:.005,decay:1.3,sustain:0,release:1.5}},organ:{engine:'additive',params:{harmonics:8,tilt:1.5,attack:.008,decay:.04,sustain:1,release:.08,cutoff:14000}},motion:{engine:'wavetable',params:{position:.65,detune:8,attack:.7,decay:.7,sustain:.7,release:2,cutoff:12000,lfoRate:1.2,lfoDepth:8}}};
function updateVolume(){$('#volume-value').textContent=Math.round(+$('#volume').value/.65*100)+'%';if(master)master.gain.setTargetAtTime(+$('#volume').value,ctx.currentTime,.02);}
$('#audio-start').onclick=enableAudio;$('#panic').onclick=panic;
$$('[data-engine]').forEach(b=>b.onclick=()=>{changeEngine(b.dataset.engine);$('#preset').value='init';});
$('#wave').onchange=e=>{waveform=e.target.value;panic();if(currentLesson===lessons.length-1)updateLab();};
$('#volume').oninput=()=>{updateVolume();updateLab();};
$('#complete').onclick=()=>{completed.add(currentLesson);storage.set('progress',[...completed]);if(currentLesson<lessons.length-1)selectLesson(currentLesson+1);else{renderNavigation();$('#lesson-result').textContent='✓ Explored';toast('All nine lessons explored. Keep building your own sounds.');}};
$('#oct-down').onclick=()=>{panic();octave=Math.max(0,octave-1);renderKeyboard();};$('#oct-up').onclick=()=>{panic();octave=Math.min(6,octave+1);renderKeyboard();};
document.addEventListener('keydown',async e=>{if(e.repeat||e.ctrlKey||e.altKey||e.metaKey||$('#help').open||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))return;const key=e.key.toLowerCase(),index=computerKeys.indexOf(key);if(index<0)return;e.preventDefault();const note=(octave+1)*12+index,id='key:'+key;heldComputer.set(key,note);if(await enableAudio())if(heldComputer.get(key)===note)startVoice(id,note,100);});
document.addEventListener('keyup',e=>{const key=e.key.toLowerCase();if(heldComputer.has(key)){heldComputer.delete(key);endVoice('key:'+key);}});window.addEventListener('blur',panic);document.addEventListener('visibilitychange',()=>{if(document.hidden)panic();});
$('#demo').onclick=async()=>{if(!await enableAudio())return;panic();const base=(octave+1)*12;[0,7,12,7,3,10,12,15].forEach((offset,i)=>{demoTimers.push(setTimeout(()=>startVoice('demo:'+i,base+offset,90),i*320));demoTimers.push(setTimeout(()=>endVoice('demo:'+i),i*320+240));});};
$('#midi-connect').onclick=connectMidi;$('#midi-input').onchange=e=>{panic();selectedInput=e.target.value;preferredInput=selectedInput;storage.set('midi-input',preferredInput);bends.clear();modulations.clear();learnTarget=null;learnQueue=[];learnLastKey=null;renderMappings();updateControllerUI();$('#midi-status').textContent='Selected: '+controllerName();};
$('#learn-all').onclick=()=>{if(learnTarget){learnTarget=null;learnQueue=[];renderMappings();return;}if(!selectedInput){toast('Connect MIDI first.');return;}learnLastKey=null;learnQueue=['cutoff','resonance','attack','decay','sustain','release','lfoRate','lfoDepth'];learnTarget=learnQueue.shift();renderMappings();toast('Move a knob or fader for Cutoff. Follow the prompts for up to eight controls, or cancel when finished.');};
$('#clear-mappings').onclick=()=>{delete maps[selectedInput];learnTarget=null;learnQueue=[];storage.set('maps',maps);renderMappings();toast('Mappings cleared for this MIDI input.');};
$('#preset').onchange=e=>{const name=e.target.value,p=presets[name]||{};applyPatch({format:'signal-school',version:1,engine:p.engine||engine,waveform:p.waveform||'sawtooth',params:{...Object.fromEntries(Object.entries(definitions).map(([k,d])=>[k,d.initial])),...p.params}});$('#preset').value=name;};
$('#save-patch').onclick=()=>{storage.set('patch',snapshot());toast('Patch saved in this browser.');};$('#load-patch').onclick=()=>{const p=storage.get('patch',null);if(!p){toast('No saved patch yet.');return;}try{applyPatch(p);toast('Saved patch loaded.');}catch(e){toast(e.message);}};
$('#export-patch').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(snapshot(),null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='signal-school-patch.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('#import-patch').onclick=()=>$('#patch-file').click();$('#patch-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>100000)throw Error('Patch file is too large.');applyPatch(JSON.parse(await file.text()));toast('Patch imported.');}catch(error){toast(error.message);}e.target.value='';};
$('#open-help').onclick=()=>$('#help').showModal();$('.dialog-close').onclick=()=>$('#help').close();$('#help').addEventListener('click',e=>{if(e.target===$('#help')){const r=$('#help').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#help').close();}});
function fitWorkspace(){const viewport=window.visualViewport;const width=viewport?.width||window.innerWidth,height=viewport?.height||window.innerHeight;const scale=Math.min(width/1440,height/960);const workspaceWidth=width/scale,workspaceHeight=height/scale;const root=document.documentElement;root.style.setProperty('--workspace-scale',scale);root.style.setProperty('--workspace-width',workspaceWidth+'px');root.style.setProperty('--workspace-height',workspaceHeight+'px');}
window.addEventListener('resize',fitWorkspace);window.visualViewport?.addEventListener('resize',fitWorkspace);fitWorkspace();
