const labSamples={
 bass:{description:'A round, punchy bass made from bright sawtooth oscillators.',recipe:['Source: sawtooth waves provide lots of harmonics. Detuning adds a little beating in the finished version.','Filter: the 650 Hz cutoff removes most of the buzz; resonance emphasizes the cutoff region.','Envelope: a 5 ms attack and short decay give a firm front edge, with a quieter held body.','Motion: 7 cents of detune adds movement without an LFO.'],experiment:'Raise Cutoff toward 2,000 Hz, then compare Sustain at 10% and 80%. Which change affects brightness, and which affects the held loudness?',notes:[36,36,43,39,36,46,43,39],spacing:300,hold:210},
 pad:{description:'A soft, slowly blooming pad, built from triangle oscillators.',recipe:['Source: triangle waves have gentler upper harmonics than sawtooth waves.','Filter: a 4 kHz low-pass cutoff keeps the upper edge soft.','Envelope: 1.3 s Attack and 2.8 s Release make chords swell and linger.','Motion: 10 cents of detune and slow, shallow vibrato give the held sound movement.'],experiment:'Play a chord if your controller supports notes. Reduce Attack to 0.01 s, then restore it. Next reduce Release to 0.1 s. Describe the difference between the beginning and the ending.',chord:[48,55,60,63],hold:2800},
 bell:{description:'A glassy, inharmonic bell using audio-rate frequency modulation.',recipe:['Source: a sine modulator runs at 2.73 times the carrier frequency. FM index 3 produces strong sidebands.','Filter: a high 17 kHz cutoff leaves most of that brightness intact.','Envelope: a fast attack, 1.3 s decay, and zero sustain make each note ring out rather than stay held.','Motion: no LFO is needed. The metallic character comes from FM; vibrato remains at zero.'],experiment:'Compare FM ratios 2.00 and 2.73 while keeping the same note. Then lower FM index toward zero. Listen for the sidebands disappearing.',notes:[60,67,72,75],spacing:650,hold:500},
 organ:{description:'An organ-like tone assembled from eight sine-wave harmonic partials.',recipe:['Source: eight harmonic partials combine into one tone. Tilt 1.5 makes higher partials progressively quieter.','Filter: the 14 kHz cutoff is quite open, preserving the harmonic structure.','Envelope: a short attack, 100% sustain, and short release keep the tone steady while a key is held.','Motion: no vibrato is added. The sustained harmonic balance creates the character.'],experiment:'Change Harmonics from 8 to 1, then back. Raise Tilt to 2.5. Keep Sustain at 100% so you can hear the harmonic changes on a held note.',chord:[48,55,60,64],hold:2000},
 motion:{description:'A wide, wavetable pad with a bright harmonic spectrum and gentle pitch movement.',recipe:['Source: Table position 65% blends saw-like and square-like harmonic spectra.','Filter: the 12 kHz cutoff preserves a bright upper spectrum.','Envelope: a 0.7 s attack and 2 s release soften the chord’s boundaries.','Motion: 8 cents of detune and shallow 1.2 Hz vibrato add beating and pitch movement. The table position is static until you move it.'],experiment:'Play a chord and sweep Table position from 0% to 100%. Then set Vibrato to zero to separate timbre changes from pitch movement.',chord:[48,55,58,62],hold:2400}
};
function labPatch(name,stage='full'){
 const preset=presets[name];if(!preset)throw Error('Unknown example patch.');
 const values={...Object.fromEntries(Object.entries(definitions).map(([k,d])=>[k,d.initial])),...preset.params};
 if(stage==='raw'){values.cutoff=18000;values.resonance=.1;}
 if(stage==='raw'||stage==='filter'){values.attack=.005;values.decay=.05;values.sustain=1;values.release=.08;}
 if(stage!=='full'){values.detune=0;values.lfoDepth=0;}
 return {format:'signal-school',version:1,engine:preset.engine,waveform:preset.waveform||'sawtooth',params:values,volume:.3};
}
function openSoundLab(){if(currentLesson!==lessons.length-1)selectLesson(lessons.length-1);updateLab();}
function updateLab(){
 const name=$('#lab-sample').value,info=labSamples[name],reference=labPatch(name);if(!info)return;
 $('#lab-description').textContent=info.description;$('#lab-experiment').textContent=info.experiment;
 $('#lab-recipe').replaceChildren();info.recipe.forEach(text=>{const li=document.createElement('li');li.textContent=text;$('#lab-recipe').append(li);});
 $('#lab-current').textContent='Loaded engine: '+engine+' · '+(engine===reference.engine?'compare values below':'different engine from this recipe');
 const table=$('#lab-parameters');table.replaceChildren();
 const addRow=(label,current,target,explanation,active=true)=>{const row=document.createElement('tr');if(current!==target)row.className='lab-changed';if(!active)row.classList.add('lab-inactive');for(const value of [label,current,target,explanation]){const cell=document.createElement('td');cell.textContent=value;cell.title=explanation;row.append(cell);}table.append(row);};
 addRow('Engine',engine,reference.engine,'How the raw signal is generated.');
 addRow('Waveform',engine==='subtractive'?waveform:'Engine-defined',reference.engine==='subtractive'?reference.waveform:'Engine-defined','Waveform selector applies only to subtractive synthesis.',reference.engine==='subtractive');
 for(const [key,d]of Object.entries(definitions)){
  const active=['cutoff','resonance','attack','decay','sustain','release','lfoRate','lfoDepth',...engineInfo[reference.engine].source].includes(key);
  addRow(d.name,d.format(params[key]),d.format(reference.params[key]),(active?'':'Unused by this recipe’s engine. ')+d.hint,active);
 }
 addRow('Output',Math.round(+$('#volume').value/.65*100)+'%',Math.round(reference.volume/.65*100)+'%','Master output level. Note velocity also affects loudness.');
}
async function auditionLab(){
 if(!await enableAudio())return;
 const name=$('#lab-sample').value,info=labSamples[name];applyPatch(labPatch(name,$('#lab-stage').value));updateLab();
 const events=info.chord?info.chord.map(note=>({note,at:0,hold:info.hold})):info.notes.map((note,i)=>({note,at:i*info.spacing,hold:info.hold}));
 events.forEach((event,i)=>{const id='lab:'+i;demoTimers.push(setTimeout(()=>startVoice(id,event.note,90),event.at));demoTimers.push(setTimeout(()=>endVoice(id),event.at+event.hold));});
}
$('#lab-play').onclick=auditionLab;$('#lab-stop').onclick=panic;
$('#lab-sample').onchange=updateLab;
$('#close-lab').onclick=()=>selectLesson(0);
$('#sound-lab').addEventListener('cancel',panic);

function setRecipeView(values){$('#sound-lab').classList.toggle('show-values',values);$('#recipe-build').setAttribute('aria-pressed',String(!values));$('#recipe-values').setAttribute('aria-pressed',String(values));}
$('#recipe-build').onclick=()=>setRecipeView(false);$('#recipe-values').onclick=()=>setRecipeView(true);
